1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	import {
7	  FIELD_LIMITS,
8	  checkIdeaContent,
9	  isCompleteIdea,
10	  normalizeIdea,
11	  fieldRulesBrowserScript,
12	  type ContentErrorCode,
13	} from './idea-fields.ts';
14	
15	const PRODUCT: string = 'FeatureHarbor';
16	const RESOURCE: string = 'ideas';
17	const MAX_BODY_BYTES = 1_000_000;
18	// 接口侧把共用的内容判定结果映射成原有的错误说明；首页另有自己的措辞。
19	const CONTENT_ERROR_MESSAGES: Record<ContentErrorCode, string> = {
20	  'title-empty': '标题去掉首尾空白后不能为空',
21	  'title-too-long': `标题最多 ${FIELD_LIMITS.title} 个字符`,
22	  'description-empty': '详细说明必须包含非空白内容',
23	  'description-too-long': `详细说明最多 ${FIELD_LIMITS.description} 个字符`,
24	  'scenario-too-long': `使用场景最多 ${FIELD_LIMITS.scenario} 个字符`,
25	};
26	const PAGE: string = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeatureHarbor · 产品意见与公开路线图</title><style>
27	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
28	a{color:#175b9c}
29	label{display:block;font-weight:600;margin-top:1rem}
30	input,textarea{width:100%;box-sizing:border-box;padding:.4rem;font:inherit}
31	textarea{resize:vertical}
32	.required{color:#b00020}
33	button{margin-top:1rem;padding:.5rem 1.2rem;font:inherit}
34	#error{color:#b00020;margin-top:.75rem}
35	#success{color:#1a7f37;margin-top:.75rem}
36	.idea{border-top:1px solid #ddd;padding:1rem 0}
37	.idea h3{margin:0 0 .5rem}
38	.pre{white-space:pre-wrap}
39	time{color:#666;font-size:.9rem}
40	</style><main><h1>FeatureHarbor</h1><p>产品意见与公开路线图</p>
41	<h2>提交产品意见</h2>
42	<form id="idea-form" novalidate>
43	<label for="f-title">标题 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.title} 字）</label>
44	<input id="f-title" name="title" required>
45	<label for="f-desc">详细说明 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.description} 字）</label>
46	<textarea id="f-desc" name="description" rows="5" required></textarea>
47	<label for="f-scenario">使用场景（可选，最多 ${FIELD_LIMITS.scenario} 字）</label>
48	<textarea id="f-scenario" name="scenario" rows="3"></textarea>
49	<button type="submit">提交意见</button>
50	<p id="error" role="alert" hidden></p>
51	<p id="success" role="status" hidden></p>
52	</form>
53	<h2>意见列表</h2>
54	<p id="empty" hidden>还没有意见记录。</p>
55	<div id="ideas"></div>
56	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
57	</main><script>
58	${fieldRulesBrowserScript}
59	const form = document.getElementById('idea-form');
60	const titleInput = document.getElementById('f-title');
61	const descInput = document.getElementById('f-desc');
62	const scenarioInput = document.getElementById('f-scenario');
63	const errorBox = document.getElementById('error');
64	const successBox = document.getElementById('success');
65	const emptyNote = document.getElementById('empty');
66	const list = document.getElementById('ideas');
67	const EMPTY_TEXT = '还没有意见记录。';
68	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
69	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
70	let listState = 'loading';
71	function showError(message) {
72	  errorBox.textContent = message;
73	  errorBox.hidden = false;
74	  successBox.hidden = true;
75	}
76	function renderIdea(idea) {
77	  const item = document.createElement('article');
78	  item.className = 'idea';
79	  const heading = document.createElement('h3');
80	  heading.textContent = idea.title;
81	  const desc = document.createElement('p');
82	  desc.className = 'pre';
83	  desc.textContent = idea.description;
84	  item.append(heading, desc);
85	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
86	    const scenario = document.createElement('p');
87	    const label = document.createElement('strong');
88	    label.textContent = '使用场景：';
89	    const text = document.createElement('span');
90	    text.className = 'pre';
91	    text.textContent = idea.scenario;
92	    scenario.append(label, text);
93	    item.append(scenario);
94	  }
95	  const time = document.createElement('time');
96	  time.dateTime = idea.createdAt;
97	  const parsed = new Date(idea.createdAt);
98	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
99	  item.append(time);
100	  return item;
101	}
102	let remoteIdeas = [];
103	// 本页已确认保存的意见，按本页发起提交的先后排列：后提交的在前。
104	// 每条记录带上点击提交时的序号，响应返回的先后不影响排列位置
105	const submittedIdeas = [];
106	function renderList() {
107	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
108	  const seen = new Set();
109	  const ordered = [];
110	  for (const entry of submittedIdeas) {
111	    const idea = entry.idea;
112	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
113	  }
114	  for (const idea of remoteIdeas) {
115	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
116	  }
117	  list.replaceChildren(...ordered.map(renderIdea));
118	  if (listState === 'failed') {
119	    emptyNote.textContent = LOAD_FAILED_TEXT;
120	    emptyNote.hidden = false;
121	  } else if (listState === 'ready') {
122	    emptyNote.textContent = EMPTY_TEXT;
123	    emptyNote.hidden = ordered.length > 0;
124	  } else {
125	    // 首次列表仍在加载，不能把等待误报成没有记录
126	    emptyNote.hidden = true;
127	  }
128	}
129	// 一条意见记录是否完整，直接使用 idea-fields.ts 注入的同一份 isCompleteIdea：
130	// 与服务读取已有数据的判定逐字相同，列表加载与提交确认都调用它，不在页面另写第二份。
131	async function loadIdeas() {
132	  try {
133	    const res = await fetch('/api/ideas');
134	    if (!res.ok) throw new Error('load failed');
135	    const data = await res.json();
136	    // 列表响应必须是带 ideas 数组的 JSON 对象，且数组中每条记录都完整；
137	    // 顶层结构异常或任意一条记录不完整都属于整次加载失败，
138	    // 即使异常记录前面有正常意见，也不能只展示其中一部分
139	    if (typeof data !== 'object' || data === null || Array.isArray(data) || !Array.isArray(data.ideas)) {
140	      throw new Error('invalid ideas response');
141	    }
142	    if (!data.ideas.every(isCompleteIdea)) throw new Error('invalid idea record');
143	    remoteIdeas = data.ideas;
144	    listState = 'ready';
145	  } catch {
146	    listState = 'failed';
147	  }
148	  renderList();
149	}
150	// 任一字段每次发生编辑都递增；提交时记下当前版本，成功响应到达时若版本未变，
151	// 说明等待期间没有继续编辑，才清空表单，否则保留正在写的草稿
152	let editVersion = 0;
153	for (const field of [titleInput, descInput, scenarioInput]) {
154	  field.addEventListener('input', () => { editVersion += 1; });
155	}
156	// 字段内容判定与接口共用同一份实现（FIELD_LIMITS、codePointCount、checkIdeaContent
157	// 由 idea-fields.ts 注入）；这里只把共用判定结果映射成本页原有的提示措辞与顺序。
158	function validate(title, description, scenario) {
159	  switch (checkIdeaContent(title, description, scenario)) {
160	    case 'title-empty': return '标题不能为空。';
161	    case 'title-too-long': return '标题最多 ' + FIELD_LIMITS.title + ' 个字符。';
162	    case 'description-empty': return '详细说明不能为空。';
163	    case 'description-too-long': return '详细说明最多 ' + FIELD_LIMITS.description + ' 个字符。';
164	    case 'scenario-too-long': return '使用场景最多 ' + FIELD_LIMITS.scenario + ' 个字符。';
165	    default: return null;
166	  }
167	}
168	// 每次点击提交都递增：成功或失败提示只属于最近一次点击。
169	// 更早发出的请求即使更晚返回，也只能在服务确认保存时更新列表，不能改动当前提示。
170	let latestSubmitSeq = 0;
171	form.addEventListener('submit', async (event) => {
172	  event.preventDefault();
173	  const submitSeq = ++latestSubmitSeq;
174	  // 用户发起新的提交后，上一条操作的提示先清除；在本次点击有结果前，
175	  // 更早请求迟到返回也不能重新显示成功或失败，也不能让人误以为正在提交的意见已保存
176	  errorBox.hidden = true;
177	  successBox.hidden = true;
178	  const title = titleInput.value;
179	  const description = descInput.value;
180	  const scenario = scenarioInput.value;
181	  const submittedVersion = editVersion;
182	  const problem = validate(title, description, scenario);
183	  // 被表单直接拦下的一次点击同样是用户最近的提交操作，字段错误即本次点击的结果；
184	  // 之后更早请求的返回不能掩盖它
185	  if (problem) { showError(problem); return; }
186	  let res;
187	  try {
188	    res = await fetch('/api/ideas', {
189	      method: 'POST',
190	      headers: { 'content-type': 'application/json' },
191	      body: JSON.stringify({ title, description, scenario })
192	    });
193	  } catch {
194	    if (submitSeq === latestSubmitSeq) showError('网络错误，提交未成功，请重试。');
195	    return;
196	  }
197	  let data = null;
198	  try { data = await res.json(); } catch { data = null; }
199	  if (!res.ok) {
200	    if (submitSeq === latestSubmitSeq) {
201	      showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
202	    }
203	    return;
204	  }
205	  // 成功状态的响应同样必须记录完整：顶层是含 idea 的 JSON 对象，
206	  // 且 idea 本身通过 isCompleteIdea 校验（对象、非空 id、各字段均为字符串）。
207	  // 空对象、数组或缺字段的记录不能当作保存成功：不显示成功提示、
208	  // 不清空草稿、不并入列表，也不用表单内容补齐响应缺失的信息
209	  const saved = typeof data === 'object' && data !== null && !Array.isArray(data) && isCompleteIdea(data.idea);
210	  if (!saved) {
211	    if (submitSeq === latestSubmitSeq) showError('提交失败，请稍后重试。');
212	    return;
213	  }
214	  const idea = data.idea;
215	  // 是否清空表单只取决于等待期间有没有继续编辑（包括改回原文、清空字段也算编辑），
216	  // 与响应返回先后无关：过期请求确认保存时也不能清掉用户正在写的草稿
217	  if (editVersion === submittedVersion) form.reset();
218	  // 只要服务确认保存，意见就进入列表，即使这条请求已不是最近一次点击：
219	  // 不能为了避免提示干扰而丢弃真实保存结果。
220	  // 位置按本页发起提交的先后确定（后提交的在前），与响应返回先后无关：
221	  // 先提交的意见迟到确认时补到后提交的意见之后，不能把它挤到更靠后的位置
222	  const entry = { seq: submitSeq, idea };
223	  let insertAt = submittedIdeas.findIndex((e) => e.seq < submitSeq);
224	  if (insertAt === -1) insertAt = submittedIdeas.length;
225	  submittedIdeas.splice(insertAt, 0, entry);
226	  renderList();
227	  // 成功提示只属于最近一次点击：更早的请求迟到返回时，不能在最新一次的失败提示
228	  // 或新一次提交的等待旁边再显示成功
229	  if (submitSeq === latestSubmitSeq) {
230	    successBox.textContent = '提交成功，你的意见已保存。';
231	    successBox.hidden = false;
232	  }
233	});
234	loadIdeas();
235	</script></html>`;
236	const args: string[] = process.argv.slice(2);
237	const help: string = `FeatureHarbor - 产品意见与公开路线图
238	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
239	       node server.ts --help
240	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
241	Port 0 selects an available port.
242	`;
243	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
244	  process.stdout.write(help);
245	  process.exit(args.length === 0 ? 2 : 0);
246	}
247	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
248	let host: string = '127.0.0.1';
249	let port: number = 8080;
250	let dataDir: string = 'data';
251	while (args.length) {
252	  const flag = args.shift();
253	  const value = args.shift();
254	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
255	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
256	  }
257	  if (flag === '--host') host = value;
258	  else if (flag === '--port') {
259	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
260	    port = Number(value);
261	  } else dataDir = value;
262	}
263	mkdirSync(dataDir, { recursive: true });
264	const dataFile = join(dataDir, 'ideas.json');
265	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
266	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
267	}
268	function respond(res: ServerResponse, status: number, value: unknown, options: { html?: boolean; allow?: string } = {}): void {
269	  const body = options.html ? String(value) : JSON.stringify(value);
270	  res.writeHead(status, { 'content-type': options.html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
271	    'content-length': Buffer.byteLength(body), ...(status === 405 ? { allow: options.allow ?? 'GET' } : {}) });
272	  res.end(body);
273	}
274	// 已有意见的结构完整性直接使用 idea-fields.ts 的 isCompleteIdea，
275	// 与首页列表加载、提交结果确认共用同一份判定。
276	function readIdeas(): unknown[] {
277	  const records: unknown = JSON.parse(readFileSync(dataFile, 'utf8'));
278	  if (!Array.isArray(records)) throw new Error('Invalid record list');
279	  // 任意一条记录不完整，整份列表都视为读取失败：
280	  // 不跳过异常记录，也不只返回正常部分。只检查结构，不套用新提交的内容限制：
281	  // 标题首尾空白、正文与场景换行、任意时间字符串都按原样保留，不补字段或改写文字。
282	  if (!records.every(isCompleteIdea)) throw new Error('Invalid idea record');
283	  return records;
284	}
285	function saveIdeas(records: unknown[]): void {
286	  const tempFile = `${dataFile}.tmp`;
287	  writeFileSync(tempFile, `${JSON.stringify(records, null, 2)}\n`);
288	  renameSync(tempFile, dataFile);
289	}
290	async function handleCreateIdea(req: IncomingMessage, res: ServerResponse): Promise<void> {
291	  const chunks: Buffer[] = [];
292	  let size = 0;
293	  for await (const chunk of req as AsyncIterable<Buffer>) {
294	    size += chunk.length;
295	    if (size > MAX_BODY_BYTES) {
296	      respond(res, 400, { error: '请求体过大' });
297	      req.destroy();
298	      return;
299	    }
300	    chunks.push(chunk);
301	  }
302	  let payload: unknown;
303	  try {
304	    payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
305	  } catch {
306	    respond(res, 400, { error: '请求体不是有效的 JSON' });
307	    return;
308	  }
309	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
310	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
311	    return;
312	  }
313	  const body = payload as Record<string, unknown>;
314	  for (const field of ['title', 'description'] as const) {
315	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
316	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
317	  }
318	  if (body.scenario !== undefined && typeof body.scenario !== 'string') {
319	    respond(res, 400, { error: '字段 scenario 必须是字符串' });
320	    return;
321	  }
322	  const rawTitle = body.title as string;
323	  const rawDescription = body.description as string;
324	  const scenario = typeof body.scenario === 'string' ? body.scenario : '';
325	  // 内容规则（空白与上限）与首页共用同一份判定，这里只保留接口原有的错误措辞。
326	  const problem = checkIdeaContent(rawTitle, rawDescription, scenario);
327	  if (problem) {
328	    respond(res, 400, { error: CONTENT_ERROR_MESSAGES[problem] });
329	    return;
330	  }
331	  const { title, description } = normalizeIdea(rawTitle, rawDescription, scenario);
332	  const idea = {
333	    id: randomUUID(),
334	    title,
335	    description,
336	    scenario,
337	    createdAt: new Date().toISOString(),
338	  };
339	  let records: unknown[];
340	  try {
341	    records = readIdeas();
342	  } catch {
343	    respond(res, 500, { error: '无法读取已有意见数据，未保存新意见' });
344	    return;
345	  }
346	  records.unshift(idea);
347	  try {
348	    saveIdeas(records);
349	  } catch {
350	    respond(res, 500, { error: '保存意见失败，请稍后重试' });
351	    return;
352	  }
353	  respond(res, 201, { idea });
354	}
355	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
356	  let route: string;
357	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
358	  if (!['/', '/health', '/api/ideas'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
359	  if (route === '/api/ideas') {
360	    if (req.method === 'POST') {
361	      handleCreateIdea(req, res).catch(() => {
362	        if (!res.headersSent) respond(res, 500, { error: '提交意见失败，请稍后重试' });
363	      });
364	      return;
365	    }
366	    if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }, { allow: 'GET, POST' }); return; }
367	    try {
368	      respond(res, 200, { [RESOURCE]: readIdeas() });
369	    } catch { respond(res, 500, { error: 'unable to read ideas' }); }
370	    return;
371	  }
372	  if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }); return; }
373	  if (route === '/') { respond(res, 200, PAGE, { html: true }); return; }
374	  respond(res, 200, { status: 'ok', product: PRODUCT });
375	});
376	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
377	server.listen(port, host, (): void => {
378	  const address = server.address();
379	  if (address && typeof address !== 'string') {
380	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
381	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
382	  }
383	});
384	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
