648	// 201 表示服务端接受了请求，但页面只承认「确认返回的完整记录」：
649	// 响应必须可解析为带 idea 的 JSON 对象，且 idea 自身结构完整（非空字符串 id，
650	// title、description、scenario、createdAt 全部存在且为字符串）。
651	// 下面的用例只覆盖「响应可解析、状态为 201、但 idea 结构异常」这一类——
652	// 响应无法解析与整条 idea 缺失已由上面的用例覆盖。
653	function malformedSuccessBodies(): Array<{ name: string; body: unknown }> {
654	  const text = {
655	    id: 'a',
656	    title: '返回的标题',
657	    description: '返回的说明',
658	    scenario: '返回的场景',
659	    createdAt: '2026-03-01T00:00:00.000Z',
660	  };
661	  const without = (field: string): Record<string, unknown> => {
662	    const record = { ...text };
663	    delete record[field];
664	    return record;
665	  };
666	  return [
667	    // 顶层不是包含 idea 的对象
668	    { name: '顶层为 null', body: null },
669	    { name: '顶层为数组', body: [{ idea: text }] },
670	    { name: '顶层为普通字符串', body: JSON.stringify({ idea: text }) },
671	    { name: '顶层为数字', body: 1 },
672	    { name: '顶层没有 idea 字段（其他字段完整）', body: { saved: true, title: text.title } },
673	    // idea 是空值、数组或普通字符串等不能代表一条意见的内容
674	    { name: 'idea 为 null', body: { idea: null } },
675	    { name: 'idea 为 undefined（字段存在但无值）', body: { idea: undefined } },
676	    { name: 'idea 为数组', body: { idea: [text] } },
677	    { name: 'idea 为普通字符串', body: { idea: '返回的标题' } },
678	    { name: 'idea 为数字', body: { idea: 1 } },
679	    // idea 是对象、也带标题和正文，但标识不合法
680	    { name: 'id 为空字符串', body: { idea: { ...text, id: '' } } },
681	    { name: 'id 缺失', body: { idea: without('id') } },
682	    { name: 'id 为数字', body: { idea: { ...text, id: 1 } } },
683	    { name: 'id 为 null', body: { idea: { ...text, id: null } } },
684	    { name: 'id 为数组', body: { idea: { ...text, id: [] } } },
685	    // 标题、详细说明、使用场景、提交时间缺失或不是字符串
686	    { name: 'title 缺失', body: { idea: without('title') } },
687	    { name: 'title 为数字', body: { idea: { ...text, title: 1 } } },
688	    { name: 'title 为 null', body: { idea: { ...text, title: null } } },
689	    { name: 'description 缺失', body: { idea: without('description') } },
690	    { name: 'description 为数字', body: { idea: { ...text, description: 1 } } },
691	    { name: 'scenario 缺失（与空字符串不同）', body: { idea: without('scenario') } },
692	    { name: 'scenario 为数字', body: { idea: { ...text, scenario: 0 } } },
693	    { name: 'scenario 为 null', body: { idea: { ...text, scenario: null } } },
694	    { name: 'createdAt 缺失', body: { idea: without('createdAt') } },
695	    { name: 'createdAt 为数字', body: { idea: { ...text, createdAt: 0 } } },
