1082	// 提交提示归属：成功或失败提示只属于最近一次点击提交。用户可以在上一条请求还没返回时
1083	// 再次点击提交，更早请求迟到的任何结果都不能改动当前提示；但旧请求被服务确认保存的意见
1084	// 仍必须进入列表。下列用例精确控制两个 POST 的返回先后与结果类型。
1085	
1086	function settleGate(g: Gate, outcome: 'network-error' | 'server-reject' | 'broken-json' | 'missing-idea' | 'malformed-idea'): void {
1087	  if (outcome === 'network-error') {
1088	    g.reject(new TypeError('Failed to fetch'));
1089	  } else if (outcome === 'server-reject') {
1090	    g.resolve(jsonResponse(400, { error: '较早一次提交被拒绝' }));
1091	  } else if (outcome === 'broken-json') {
1092	    g.resolve(brokenJsonResponse(201));
1093	  } else if (outcome === 'malformed-idea') {
1094	    // 可解析的 201：标题、正文、场景都带回来了，但缺少 createdAt，记录结构仍不完整
1095	    g.resolve(jsonResponse(201, {
1096	      idea: { id: 'stale', title: '迟到的标题', description: '迟到的说明', scenario: '' },
1097	    }));
1098	  } else {
1099	    g.resolve(jsonResponse(201, { saved: true }));
1100	  }
1101	}
