const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
let listState = 'loading';
// 已生效的搜索关键词：去掉首尾空白后的完整一段文字，空字符串表示不搜索。
